"use client";
import { useState } from "react";
export default function SupportTicketForm() { const [form, setForm] = useState({ category: "TRANSFER", priority: "NORMAL", subject: "", message: "" }); const [notice, setNotice] = useState(""); async function submit() { const response = await fetch("/api/support", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form) }); const data = await response.json(); setNotice(response.ok ? "Your support request was submitted." : data.error || "Unable to submit request."); if (response.ok) setForm({ category: "TRANSFER", priority: "NORMAL", subject: "", message: "" }); } return <div className="rounded-2xl border border-slate-800 bg-slate-900 p-6 shadow-xl"><h2 className="text-base font-semibold text-white">Open a support request</h2><div className="mt-5 grid grid-cols-1 gap-4 sm:grid-cols-2"><select value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} className="rounded-xl border border-slate-800 bg-slate-950 px-4 py-3 text-sm text-slate-200"><option value="TRANSFER">Transfer help</option><option value="ACCOUNT">Account help</option><option value="SECURITY">Security</option><option value="CARD">Card support</option></select><select value={form.priority} onChange={(e) => setForm({ ...form, priority: e.target.value })} className="rounded-xl border border-slate-800 bg-slate-950 px-4 py-3 text-sm text-slate-200"><option>NORMAL</option><option>HIGH</option><option>URGENT</option></select><input value={form.subject} onChange={(e) => setForm({ ...form, subject: e.target.value })} placeholder="Subject" className="rounded-xl border border-slate-800 bg-slate-950 px-4 py-3 text-sm text-white sm:col-span-2" /><textarea value={form.message} onChange={(e) => setForm({ ...form, message: e.target.value })} rows={5} placeholder="Describe the issue" className="rounded-xl border border-slate-800 bg-slate-950 px-4 py-3 text-sm text-white sm:col-span-2" /></div><div className="mt-4 flex items-center justify-between"><p className="text-xs text-slate-400">{notice}</p><button onClick={submit} className="rounded-xl bg-indigo-600 px-5 py-2.5 text-xs font-semibold text-white">Submit request</button></div></div>; }